import { Heap } from "#base/scripts/heap.js";
import { QuadTree } from "#base/scripts/quadtree.js";
import { RandomImpl } from "#base/scripts/random-pcg-32.js";
import { RegionType } from "#base/scripts/voronoi-types.js";
import { RegionCell, WrapDistOptions } from "#base/scripts/voronoi-utils.js";
import { Rule, ScoringContext } from "#base/scripts/voronoi_rules/rules-base.js";

class IdScorePair {
	id = 0;
	score = 0;
	cycle = 0; // Tracks the cycle in which this score was generated, to know how stale it is.
	pairId = -1; // tracks the unique id of the score pair.
}

export abstract class VoronoiRegion {
	name: string;
	id = 0;
	groupId = 0;
	type: RegionType = 0;
	maxArea = 0;
	playerAreas = 0;
	color: float3 = { x: 0.0, y: 0.0, z: 0.0 };
	seedLocation: float2 = { x: 0.0, y: 0.0 };

	latestAddedCell: RegionCell | null = null;
	ruleSetKey?: string;
	minOrder = 0; // Used for offsetting the order of individual cells, for visualizing and debugging region growth over time.
	cellCount = 0;

	private considerationHeap: Heap<IdScorePair> = new Heap<IdScorePair>((a, b) => b.score - a.score);
	private latestScorePairId: Uint32Array = new Uint32Array(0);
	private nextScorePairId = 0;
	private cycle = 0; // Tracks the number of growStep() calls

	private dynamicRules: Rule[] = [];
	private staticRules: Rule[] = [];
	private staticScores: Float32Array = new Float32Array(0);

	private scoringContext: ScoringContext | undefined;
	private quadTree: QuadTree<RegionCell> | undefined;

	constructor(name: string, id: number, groupId: number, type: RegionType, maxArea: number, playerAreas: number) {
		this.name = name;
		this.id = id;
		this.groupId = groupId;
		this.type = type;
		this.maxArea = maxArea;
		this.playerAreas = playerAreas;
	}

	abstract setRegionIdForCell(cell: RegionCell, id: number, scoringContext: ScoringContext): void;
	abstract getRegionIdForCell(cell: RegionCell): number;
	abstract isCellClaimed(cell: RegionCell): boolean;

	pushConsideration(cellId: number, score: number): void {
		const pair: IdScorePair = { id: cellId, score: score, pairId: this.nextScorePairId, cycle: this.cycle };
		this.considerationHeap.push(pair);
		this.latestScorePairId[cellId] = this.nextScorePairId++;
	}

	prepareGrowth(
		regionCells: RegionCell[],
		regions: VoronoiRegion[],
		rules: Record<string, Rule>,
		worldDims: float2,
		plateRegions: PlateRegion[],
		wrap: WrapDistOptions,
	): void {
		this.scoringContext = {
			cells: regionCells,
			region: this,
			regions: regions,
			plateRegions: plateRegions,
			m_worldDims: { x: worldDims.x, y: worldDims.y },
			totalArea: 0.0,
			cellCount: 0,
			rules: rules,
			wrap: wrap,
		};
		this.staticRules = [];
		this.dynamicRules = [];
		for (const rule of Object.values(rules)) {
			if (rule.isActive) {
				rule.prepare();
				if (rule.isStatic) {
					this.staticRules.push(rule);
				} else {
					this.dynamicRules.push(rule);
				}
			}
		}
		regionCells.forEach((cell: RegionCell) => {
			cell.regionConsiderationBits = 0n;
		});

		this.quadTree = undefined;

		this.considerationHeap.clear();
		this.latestScorePairId = new Uint32Array(regionCells.length);
		this.staticScores = new Float32Array(regionCells.length);
		this.staticScores.fill(NaN);
		this.nextScorePairId = 0;
		this.cycle = 0;
	}

	growStep(): boolean {
		let newCellPair: IdScorePair | undefined = undefined;
		const regionCells: RegionCell[] = this.scoringContext!.cells;

		// Grab the considered item with the highest score
		while (this.considerationHeap.size > 0) {
			const pair = this.considerationHeap.pop()!;
			const cell = regionCells[pair.id];
			if (this.isCellClaimed(cell)) {
				continue;
			}
			if (this.latestScorePairId[pair.id] != pair.pairId) {
				// This score is stale, skip it and try again.
				continue;
			}

			if (pair.cycle < this.cycle - 1) {
				pair.score = this.scoreCell(cell, this.scoringContext!);
			}
			const nextHighestScore = this.considerationHeap.peek()?.score ?? -Infinity;
			if (pair.score >= nextHighestScore) {
				newCellPair = pair;
				break;
			} else {
				// No longer highest after re-score, push back on the heap and try again.
				pair.pairId = this.nextScorePairId++;
				pair.cycle = this.cycle;
				this.latestScorePairId[pair.id] = pair.pairId;
				this.considerationHeap.push(pair);
			}
		}
		if (newCellPair === undefined || newCellPair.score < 0) {
			// Possible all cells on the considerationList have been claimed by other regions, or no remaining cells have a valid score.
			return false;
		}

		const newCellId: number = newCellPair.id;

		// Assign region and update total area of this region.
		const newCell: RegionCell = regionCells[newCellId];
		newCell.regionConsiderationBits = 0n;
		this.setRegionIdForCell(newCell, this.id, this.scoringContext!);
		this.scoringContext!.totalArea += newCell.area;
		this.scoringContext!.cellCount++;
		this.cellCount = this.scoringContext!.cellCount;
		this.latestAddedCell = newCell;
		//console.log("Assigning region " + region.id + " to cell " + newCellId);

		if (this.quadTree) {
			this.quadTree.insert(newCell);
		}
		Object.values(this.scoringContext!.rules).forEach((rule: Rule) =>
			rule.notifySelectedCell(newCell, this.scoringContext!),
		);

		// Consider new neighbors and update scores
		for (const neighborId of newCell.cell.getNeighborIds()) {
			const neighbor = regionCells[neighborId];
			if (this.isCellClaimed(neighbor)) {
				continue; // cell already claimed
			}
			const score = this.scoreCell(neighbor, this.scoringContext!);

			const pairId = this.nextScorePairId++;
			this.latestScorePairId[neighborId] = pairId;
			this.considerationHeap.push({ id: neighborId, score, cycle: this.cycle, pairId });
		}

		++this.cycle;
		return this.considerationHeap.size > 0 && this.scoringContext!.totalArea < this.maxArea;
	}

	public logStats() {
		console.log(
			"Region " +
				this.id +
				" total area: " +
				this.scoringContext?.totalArea +
				", cell count: " +
				this.scoringContext?.cellCount,
		);
	}

	private scoreCell(regionCell: RegionCell, scoringContext: ScoringContext): number {
		let score = 0;
		let staticScore = this.staticScores[regionCell.id];
		if (Number.isNaN(staticScore)) {
			staticScore = 0;
			for (const rule of this.staticRules) {
				staticScore += rule.score(regionCell, scoringContext) * rule.weight;
			}
			this.staticScores[regionCell.id] = staticScore;
		}
		score += staticScore;
		for (const rule of this.dynamicRules) {
			score += rule.score(regionCell, scoringContext) * rule.weight;
		}
		return score;
	}

	public scoreSingleCell(regionCell: RegionCell) {
		return this.scoreCell(regionCell, this.scoringContext!);
	}

	public SetQuadTree(quadtree: QuadTree<RegionCell>) {
		this.quadTree = quadtree;
	}
}

export class LandmassRegion extends VoronoiRegion {
	setRegionIdForCell(cell: RegionCell, id: number, scoringContext: ScoringContext): void {
		cell.landmassId = id;
		cell.landmassOrder = scoringContext.cellCount;
	}

	getRegionIdForCell(cell: RegionCell): number {
		return cell.landmassId;
	}

	isCellClaimed(cell: RegionCell): boolean {
		return cell.landmassId != 0;
	}
}

export class PlateRegion extends VoronoiRegion {
	public m_movement: float2 = { x: 0, y: 0 };
	public m_rotation = 0;

	constructor(name: string, id: number, type: RegionType, maxArea: number) {
		super(name, id, 0, type, maxArea, 0);

		// Random movement & rotation
		const dir = RandomImpl.fRand("Plate Movement Direction") * Math.PI * 2.0;
		const movementSpeed = RandomImpl.fRand("Plate Movement Speed");
		this.m_movement.x = Math.cos(dir) * movementSpeed;
		this.m_movement.y = Math.sin(dir) * movementSpeed;
		this.m_rotation = RandomImpl.fRand("Plate Rotation") * 2.0 - 1.0;
	}

	setRegionIdForCell(cell: RegionCell, id: number, scoringContext: ScoringContext): void {
		cell.plateId = id;
		cell.plateOrder = scoringContext.cellCount;
	}

	getRegionIdForCell(cell: RegionCell): number {
		return cell.plateId;
	}

	isCellClaimed(cell: RegionCell): boolean {
		return cell.plateId != -1;
	}
}
